/*
<Group description="Fundo e Cores Base" selector="body">
  <Variable name="body.background" description="Fundo Geral" type="background" color="#0a0a14" default="$(color) none repeat scroll top left" value="$(color) none repeat scroll top left"/>
  <Variable name="main.color" description="Cor Neon / Destaque" type="color" default="#00e5ff" value="#00e5ff"/>
  <Variable name="theme.text" description="Cor do Texto" type="color" default="#e2e8f0" value="#e2e8f0"/>
  <Variable name="header.bg" description="Fundo do Cabeçalho" type="color" default="#0a0a14" value="#0a0a14"/>
  <Variable name="footer.bg" description="Fundo do Rodapé" type="color" default="#050509" value="#050509"/>
</Group>
<Group description="Tipografia" selector="body">
  <Variable name="body.font" description="Fonte do Texto" type="font" default="normal normal 16px system-ui,-apple-system,sans-serif" value="normal normal 16px system-ui,-apple-system,sans-serif"/>
</Group>
*/

:root {
  --sl-bg-body:        $(body.background);
  --sl-text-main:      $(theme.text);
  --sl-primary:        $(main.color);
  --sl-card-bg:        rgba(255,255,255,0.04);
  --sl-footer-bg:      #050509;
  --sl-radius-lg:      12px;
  --sl-radius-sm:      6px;
  --sl-transition:     all 0.3s cubic-bezier(0.4,0,0.2,1);
  --sl-btn-radius:     0;
  --sl-btn-shadow:     0 0 20px rgba(0,229,255,0.25);
  --sl-font-family:    system-ui,-apple-system,sans-serif;
  --sl-heading-weight: 900;
  /* Alias para compatibilidade com padroes_design do impl.json */
  --sd-primary:        var(--sl-primary);
}

[[DYNAMIC_CSS]]

body {
  background-color: var(--sl-bg-body,#0a0a14);
  color: var(--sl-text-main,#e2e8f0);
  font-family: var(--sl-font-family,system-ui,sans-serif);
  margin:0; padding:0; overflow-x:hidden;
  -webkit-font-smoothing:antialiased;
}
img { max-width:100%; height:auto; display:block; }
a { color:var(--sl-primary); text-decoration:none; transition:var(--sl-transition); }
a:hover { filter:brightness(0.85); }
h1,h2,h3,h4,h5,h6 { font-weight:var(--sl-heading-weight); }

/* ── GLASSMORPHISM NAV ────────────────────────────────── */
.sl-nav {
  position: sticky;
  top: 0;
  z-index: 1030;
  background: rgba(10,10,20,0.72) !important;
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border-bottom: 1px solid rgba(255,255,255,0.07) !important;
}
.port-nav-link {
  color: rgba(255,255,255,0.75) !important;
  font-weight: 600;
  font-size: .875rem;
  letter-spacing: .03em;
  padding: 8px 14px !important;
  border-radius: 4px;
  transition: var(--sl-transition);
}
.port-nav-link:hover,.port-nav-link.active {
  color: var(--sl-primary) !important;
  background: rgba(255,255,255,0.05);
  filter: none;
}
.port-brand {
  font-weight: 900;
  font-size: 1.15rem;
  letter-spacing: -.02em;
  color: var(--sl-primary) !important;
  text-decoration: none;
}
.port-brand:hover { filter:none; opacity:.85; }

/* ── HERO SECTION ─────────────────────────────────────── */
.hero-section {
  min-height: 88vh;
  display: flex;
  align-items: center;
  position: relative;
  overflow: hidden;
  padding: 5rem 0;
}
.hero-title {
  font-size: clamp(2.8rem,7vw,5.5rem);
  line-height: 1.08;
  font-weight: 900;
  letter-spacing: -.03em;
  margin-bottom: 1.5rem;
}
.hero-section::before {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse 80% 60% at 50% 0%, color-mix(in srgb,var(--sl-primary) 12%,transparent) 0%, transparent 70%);
  pointer-events: none;
}
.hero-section::after {
  content: '';
  position: absolute;
  bottom: -2px;
  left: 0; right: 0;
  height: 100px;
  background: linear-gradient(to top, var(--sl-bg-body,#0a0a14) 0%, transparent 100%);
  pointer-events: none;
}
/* Neon text — base (impl.json sobrescreve se disponível) */
.neon-text {
  color: var(--sl-primary);
  text-shadow: 0 0 20px color-mix(in srgb,var(--sl-primary) 50%,transparent),
               0 0 60px color-mix(in srgb,var(--sl-primary) 20%,transparent);
}

/* ── NEON BUTTON ──────────────────────────────────────── */
.btn-neon {
  display: inline-block;
  padding: 12px 28px;
  background-color: var(--sl-primary);
  color: #000 !important;
  font-weight: 800;
  font-size: .875rem;
  text-transform: uppercase;
  letter-spacing: .08em;
  border-radius: 0;
  border: 2px solid var(--sl-primary);
  transition: var(--sl-transition);
  text-decoration: none;
  cursor: pointer;
}
.btn-neon:hover {
  background: transparent;
  color: var(--sl-primary) !important;
  box-shadow: 0 0 20px color-mix(in srgb,var(--sl-primary) 35%,transparent),
              inset 0 0 20px color-mix(in srgb,var(--sl-primary) 10%,transparent);
  filter: none;
}
.btn-neon-outline {
  display: inline-block;
  padding: 12px 28px;
  background: transparent;
  color: var(--sl-primary) !important;
  font-weight: 800;
  font-size: .875rem;
  text-transform: uppercase;
  letter-spacing: .08em;
  border-radius: 0;
  border: 2px solid var(--sl-primary);
  transition: var(--sl-transition);
  text-decoration: none;
}
.btn-neon-outline:hover {
  background: var(--sl-primary);
  color: #000 !important;
  filter: none;
}

/* ── SERVICES SECTION ─────────────────────────────────── */
.port-services { padding:5rem 0; }
.port-section-label {
  font-size: .7rem;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: .14em;
  color: var(--sl-primary);
  margin-bottom: .5rem;
}

/* ── PROJECT CARDS (borderless) ───────────────────────── */
.card-portfolio {
  border: none !important;
  background: transparent;
  overflow: hidden;
  border-radius: var(--sl-radius-lg);
  transition: var(--sl-transition);
  position: relative;
}
.card-portfolio::after {
  content: '';
  position: absolute;
  inset: 0;
  border: 1px solid transparent;
  border-radius: var(--sl-radius-lg);
  transition: var(--sl-transition);
}
.card-portfolio:hover::after {
  border-color: var(--sl-primary);
  box-shadow: 0 0 0 1px var(--sl-primary), 0 8px 32px rgba(0,0,0,0.4);
}
.card-portfolio:hover { transform:translateY(-5px); }
.card-portfolio-img {
  width: 100%;
  aspect-ratio: 4/3;
  object-fit: cover;
  display: block;
  border-radius: var(--sl-radius-lg) var(--sl-radius-lg) 0 0;
  transition: transform .5s cubic-bezier(0.165,0.84,0.44,1);
}
.card-portfolio:hover .card-portfolio-img { transform:scale(1.06); }
.card-portfolio-body {
  padding: 1.25rem .5rem;
}
.card-portfolio-tag {
  font-size: .7rem;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: .1em;
  color: var(--sl-primary);
  margin-bottom: .4rem;
  display: block;
}
.card-portfolio-title { font-size:1rem; font-weight:700; line-height:1.3; color:var(--sl-text-main); }
.card-portfolio-title:hover { color:var(--sl-primary); filter:none; }

/* ── ANIMATE-UP ────────────────────────────────────────── */
.animate-up {
  opacity: 0;
  transform: translateY(40px);
  transition: opacity 0.8s cubic-bezier(0.165,0.84,0.44,1), transform 0.8s cubic-bezier(0.165,0.84,0.44,1);
}
.animate-up.visible { opacity:1; transform:translateY(0); }

/* ── SINGLE PROJECT (no sidebar, centered) ────────────── */
.port-post-wrap { max-width:820px; margin:0 auto; }
.port-post-hero { border-radius:var(--sl-radius-lg); overflow:hidden; margin-bottom:2rem; }
.port-post-hero img { width:100%; aspect-ratio:21/9; object-fit:cover; display:block; }
.port-post-meta {
  display:flex; flex-wrap:wrap; gap:1.25rem;
  padding:.75rem 0; margin-bottom:1.75rem;
  border-top:1px solid rgba(255,255,255,0.08);
  border-bottom:1px solid rgba(255,255,255,0.08);
  font-size:.85rem; color:#94a3b8;
}
.port-post-body { font-size:1.06rem; line-height:1.85; }
.port-post-body h2 { margin-top:2.5rem; padding-bottom:.5rem; border-bottom:1px solid rgba(255,255,255,0.08); }
.port-post-body h3 { margin-top:1.75rem; }
.port-post-body p { margin-bottom:1.4rem; }
.port-post-body img { border-radius:var(--sl-radius-sm); margin:1rem auto; }
.port-post-body a { text-decoration:underline; text-decoration-color:color-mix(in srgb,var(--sl-primary) 50%,transparent); text-underline-offset:3px; }
.port-post-body iframe,.port-post-body object,.port-post-body embed { max-width:100%; }
.port-post-body blockquote {
  margin:2rem 0; padding:1.5rem 2rem;
  border-left:3px solid var(--sl-primary);
  background:rgba(255,255,255,0.03);
  font-style:italic; font-size:1.1rem; line-height:1.65;
}
.port-post-body blockquote p { margin-bottom:0; }

/* Project links bar (demo / code) */
.port-links { display:flex; flex-wrap:wrap; gap:.75rem; margin-top:2rem; padding-top:1.5rem; border-top:1px solid rgba(255,255,255,0.08); }

/* ── SCROLL TO TOP ─────────────────────────────────────── */
#btnScrollToTop {
  position: fixed;
  bottom: 30px; right: 30px;
  width: 48px; height: 48px;
  background: var(--sl-primary);
  color: #000;
  border: none; border-radius: 0;
  display: none;
  align-items: center; justify-content: center;
  font-size: 1.2rem; cursor:pointer; z-index:999;
  transition: var(--sl-transition);
}
#btnScrollToTop:hover { box-shadow: 0 0 20px color-mix(in srgb,var(--sl-primary) 50%,transparent); }

/* ── VIDEO RESPONSIVO ──────────────────────────────────── */
.mag-video-wrapper {
  position:relative; width:100%; padding-bottom:56.25%;
  height:0; border-radius:var(--sl-radius-lg); overflow:hidden; margin:1.5rem 0;
}
.mag-video-wrapper iframe { position:absolute; top:0; left:0; width:100%; height:100%; }

/* ── FOOTER / CONTACT ──────────────────────────────────── */
.sl-footer { background:var(--sl-footer-bg,#050509); color:#64748b; border-top:1px solid rgba(255,255,255,0.06); }
.sl-footer a { color:#94a3b8; font-size:.875rem; }
.sl-footer a:hover { color:#e2e8f0; filter:none; }
.sl-footer-divider { border-color:rgba(255,255,255,0.07) !important; }
.port-contact-email { font-size:clamp(1.4rem,3vw,2.2rem); font-weight:800; letter-spacing:-.02em; }
.port-contact-email:hover { color:var(--sl-primary) !important; filter:none; }

/* ── RESPONSIVE ─────────────────────────────────────────── */
@media (max-width:991.98px) {
  .hero-section { min-height:70vh; padding:4rem 0; }
  .port-post-hero img { aspect-ratio:16/9; }
}
@media (max-width:575.98px) {
  .hero-title { font-size:clamp(2rem,10vw,3rem); }
  .btn-neon,.btn-neon-outline { padding:10px 20px; font-size:.8rem; }
}

