  //
  (function(){

    // Mobile nav toggle
    var toggle = document.getElementById('port-nav-toggle');
    var mobileNav = document.getElementById('port-nav-mobile');
    if (toggle && mobileNav) {
      toggle.addEventListener('click', function(){ mobileNav.classList.toggle('d-none'); });
    }

    // Smooth scroll for anchor links
    document.querySelectorAll('a[href^="#"]').forEach(function(a){
      a.addEventListener('click', function(e){
        var target = document.querySelector(a.getAttribute('href'));
        if (target) {
          e.preventDefault();
          target.scrollIntoView({ behavior:'smooth', block:'start' });
          if (mobileNav && !mobileNav.classList.contains('d-none')) mobileNav.classList.add('d-none');
        }
      });
    });

    // Active anchor nav link on scroll
    var sections = ['sobre','servicos','projetos','contato'].map(function(id){ return document.getElementById(id); }).filter(Boolean);
    var navLinks  = document.querySelectorAll('.port-nav-link[href^="#"]');
    if (sections.length && navLinks.length) {
      var observer = new IntersectionObserver(function(entries){
        entries.forEach(function(entry){
          if (entry.isIntersecting) {
            navLinks.forEach(function(l){ l.classList.remove('active'); });
            var active = document.querySelector('.port-nav-link[href="#'+entry.target.id+'"]');
            if (active) active.classList.add('active');
          }
        });
      }, { threshold: 0.4 });
      sections.forEach(function(s){ observer.observe(s); });
    }

    // Animate-up via IntersectionObserver
    var animEls = document.querySelectorAll('.animate-up');
    if (animEls.length) {
      var animObs = new IntersectionObserver(function(entries){
        entries.forEach(function(entry){
          if (entry.isIntersecting) { entry.target.classList.add('visible'); animObs.unobserve(entry.target); }
        });
      }, { threshold: 0.15 });
      animEls.forEach(function(el){ animObs.observe(el); });
    }

    // Scroll-to-top button
    var scrollBtn = document.getElementById('btnScrollToTop');
    if (scrollBtn) {
      window.addEventListener('scroll', function(){
        scrollBtn.style.display = window.scrollY > 400 ? 'flex' : 'none';
      });
    }

  })();
  //





  //
  (function(){
    var grid = document.getElementById('sl-related-ready');
    if (!grid) return;
    function esc(s){ return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;'); }
    var label      = (document.getElementById('sl-post-label')||{}).textContent.trim();
    var currentUrl = (document.getElementById('sl-post-url')  ||{}).textContent.trim();
    if (!label) { var rp=grid.closest('.sl-related-posts'); if(rp) rp.style.display='none'; return; }
    fetch('/feeds/posts/default/-/'+encodeURIComponent(label)+'?alt=json&max-results=4')
      .then(function(r){ if(!r.ok) throw 0; return r.json(); })
      .then(function(data){
        var entries=(data.feed.entry||[]).filter(function(e){
          var l=(e.link||[]).filter(function(l){ return l.rel==='alternate'; })[0];
          return l && l.href!==currentUrl;
        }).slice(0,3);
        if(!entries.length){ var rp2=grid.closest('.sl-related-posts'); if(rp2) rp2.style.display='none'; return; }
        grid.innerHTML=entries.map(function(e){
          var l=(e.link||[]).filter(function(l){ return l.rel==='alternate'; })[0];
          var url=esc(l?l.href:'#');
          var title=esc((e.title||{}).$t||'');
          var cat=esc(((e.category||[])[0]||{}).term||'');
          var raw=(e.media$thumbnail||{}).url||'';
          var thumb=esc(raw?raw.replace(/\/s[\d]+-c(\/|$)/,'/w400-h300-c/'):'[[PLACEHOLDER_IMG]]');
          return '<div class="col">'
            +'<article class="card-portfolio">'
            +'<a href="'+url+'"><img src="'+thumb+'" alt="'+title+'" loading="lazy" class="card-portfolio-img"/></a>'
            +'<div class="card-portfolio-body">'
            +(cat?'<span class="card-portfolio-tag">'+cat+'</span>':'')
            +'<a class="card-portfolio-title d-block text-decoration-none" href="'+url+'">'+title+'</a>'
            +'</div></article></div>';
        }).join('');
      })
      .catch(function(){ var rp3=grid.closest('.sl-related-posts'); if(rp3) rp3.style.display='none'; });
  })();
  //




  [[NICHO_JS]]
